begin;
insert into auth.users(id,email_confirmed_at) values('00000000-0000-4000-8000-000000009001',now()),('00000000-0000-4000-8000-000000009002',now());
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000009001';
select public.create_business('Ofertas locais sintéticas','ofertas-local-test','empresa','mundo-novo-ms') as bid \gset
select public.offer_command(:'bid','00000000-0000-4000-8000-000000009101','save','{"kind":"service","name":"Limpeza de telhados","areaId":"limpeza","activityIds":["limpeza-telhados"],"pricingType":"quote","active":true}');
select public.offer_command(:'bid','00000000-0000-4000-8000-000000009102','save','{"kind":"product","name":"Tinta acrílica","areaId":"pintura","activityIds":["tintas"],"pricingType":"fixed","priceCents":1999,"active":true,"featured":true}');
select public.offer_command(:'bid','00000000-0000-4000-8000-000000009103','save','{"kind":"service","name":"Instalação de câmeras","areaId":"seguranca-eletronica","activityIds":["cameras"],"pricingType":"starting-at","priceCents":10000,"active":true}');
select test.assert_true((select price_amount_cents is null from public.business_offers where id='00000000-0000-4000-8000-000000009101'),'quote null');
select test.assert_true(jsonb_array_length(public.offers_query(:'bid',null,true))=3,'owner private view');
select test.expect_error(format('select public.offer_command(%L,%L,%L,%L)',:'bid','00000000-0000-4000-8000-000000009104','save','{"kind":"product","name":"Inválido","areaId":"pintura","activityIds":["cameras"],"pricingType":"fixed","priceCents":0}'),'22023','activity belongs to selected area');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000009002';
select test.assert_true((select count(*)=0 from public.business_offers),'other owner cannot read draft');
select test.expect_error(format('select public.offers_query(%L,null,true)',:'bid'),'42501','third party private API refused');
select test.expect_error(format('select public.offer_command(%L,%L,%L)',:'bid','00000000-0000-4000-8000-000000009101','delete'),'42501','third party delete refused');
set local role anon;
set local request.jwt.claim.sub='';
select test.assert_true(jsonb_array_length(public.search_unified('telhados','mundo-novo-ms'))=0,'draft offers absent in search');
select test.assert_true((select count(*)=0 from public.business_offers),'draft offers absent direct API');
reset role;
-- Somente transação local: simula estado público para testar isolamento; rollback final.
update public.businesses set status='published' where id=:'bid';
insert into public.business_service_areas(business_id,city_id) values(:'bid','mundo-novo-ms') on conflict do nothing;
set local role anon;
select test.assert_true(jsonb_array_length(public.search_unified('telhado','mundo-novo-ms','','service'))=1,'singular roof service');
select test.assert_true(jsonb_array_length(public.search_unified('tintas','mundo-novo-ms','','product'))=1,'plural paint product');
select test.assert_true(jsonb_array_length(public.search_unified('camera','mundo-novo-ms','','service'))=1,'camera accents');
select test.assert_true(jsonb_array_length(public.search_unified('camera','mundo-novo-ms','','product'))=0,'camera service not product');
select test.assert_true(jsonb_array_length(public.search_unified('telhado','guaira-pr'))=0,'served city isolation');
select test.assert_true(jsonb_array_length(public.search_unified('camera','mundo-novo-ms','eletrica','service'))=0,'broad electrical category cannot imply camera activity');
reset role;
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000009001';
select public.offer_command(:'bid','00000000-0000-4000-8000-000000009101','save',jsonb_build_object('kind','service','name','Limpeza de telhados','areaId','limpeza','activityIds',jsonb_build_array('limpeza-telhados'),'pricingType','quote','active',false,'expectedUpdatedAt',(select updated_at from public.business_offers where id='00000000-0000-4000-8000-000000009101')));
select test.expect_error('update public.business_offers set active=true','42501','direct writes forbidden');
select public.offer_command(:'bid','00000000-0000-4000-8000-000000009102','delete');
set local role anon;
set local request.jwt.claim.sub='';
select test.assert_true(jsonb_array_length(public.search_unified('telhados','mundo-novo-ms'))=0,'hidden service absent');
select test.assert_true(jsonb_array_length(public.search_unified('tinta','mundo-novo-ms'))=0,'deleted product absent');

reset role;
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000009001';
select test.expect_error(format('select public.offer_command(%L,%L,%L,%L)',:'bid',gen_random_uuid(),'save','{"kind":"product","name":"Preço ausente","areaId":"pintura","activityIds":["tintas"],"pricingType":"fixed","active":true}'),'23514','fixed price cannot be null');
select public.offer_command(:'bid','00000000-0000-4000-8000-000000009103','prepare_image','{"imageId":"00000000-0000-4000-8000-000000009201"}');
select test.expect_error(format('select public.offer_command(%L,%L,%L,%L)',:'bid','00000000-0000-4000-8000-000000009103','finalize_image','{"imageId":"00000000-0000-4000-8000-000000009201"}'),'22023','incomplete upload cannot finalize');
insert into storage.objects(bucket_id,name,metadata) values('business-offers',:'bid'||'/00000000-0000-4000-8000-000000009103/00000000-0000-4000-8000-000000009201.webp','{"mimetype":"image/webp","size":100}');
select public.offer_command(:'bid','00000000-0000-4000-8000-000000009103','finalize_image','{"imageId":"00000000-0000-4000-8000-000000009201"}');
select test.assert_true((select image_id='00000000-0000-4000-8000-000000009201' from public.business_offers where id='00000000-0000-4000-8000-000000009103'),'ready image selected');
select public.offer_command(:'bid',gen_random_uuid(),'save',jsonb_build_object('kind','product','name','Destaque '||i,'areaId','pintura','activityIds',jsonb_build_array('tintas'),'pricingType','quote','featured',true)) from generate_series(1,5)i;
select test.expect_error(format('select public.offer_command(%L,%L,%L,%L)',:'bid',gen_random_uuid(),'save','{"kind":"product","name":"Sexto destaque","areaId":"pintura","activityIds":["tintas"],"pricingType":"quote","featured":true}'),'54000','sixth featured product rejected');
reset role;
insert into private.platform_admins(user_id) values('00000000-0000-4000-8000-000000009002');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000009002';
select public.moderate_offer('00000000-0000-4000-8000-000000009103',true,'Ensaio local de moderação');
set local role anon;
set local request.jwt.claim.sub='';
select test.assert_true(jsonb_array_length(public.search_unified('camera','mundo-novo-ms'))=0,'moderated offer not searchable');
select test.assert_true((select count(*)=0 from storage.objects where bucket_id='business-offers'),'moderated image not readable');
reset role;
select test.assert_true((select count(*)>0 from private.offer_audit where action='block'),'moderation audited');
reset role;
insert into public.work_posts(id,business_id,title,description) values('00000000-0000-4000-8000-000000009301',:'bid','Post local privado','Somente ensaio SQL');
insert into public.personal_posts(id,author_id,title,description) values('00000000-0000-4000-8000-000000009302','00000000-0000-4000-8000-000000009001','Post pessoal privado','Somente ensaio SQL');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000009001';
select public.set_post_offer('professional','00000000-0000-4000-8000-000000009301','00000000-0000-4000-8000-000000009101');
select public.set_post_offer('personal','00000000-0000-4000-8000-000000009302','00000000-0000-4000-8000-000000009101');
select test.assert_true(public.get_post_offer('professional','00000000-0000-4000-8000-000000009301')->>'name'='Limpeza de telhados','owner post link');
select test.assert_true(public.get_post_offer('personal','00000000-0000-4000-8000-000000009302')->>'name'='Limpeza de telhados','personal author can link own offer');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000009002';
select test.expect_error($q$select public.set_post_offer('professional','00000000-0000-4000-8000-000000009301','00000000-0000-4000-8000-000000009103')$q$,'42501','other author cannot replace link');
select test.assert_true(public.get_post_offer('professional','00000000-0000-4000-8000-000000009301') is null,'other author cannot read private link');
set local role anon;
set local request.jwt.claim.sub='';
select test.assert_true(public.get_post_offer('personal','00000000-0000-4000-8000-000000009302') is null,'anonymous cannot read private link');
reset role;
delete from public.work_posts where id='00000000-0000-4000-8000-000000009301';
delete from public.personal_posts where id='00000000-0000-4000-8000-000000009302';
select test.assert_true((select count(*)=0 from public.post_offer_links),'deleting post leaves no broken link');
rollback;
